mapper.select:
SELECT o.order_id, o.order_no, o.customer_name, o.customer_phone, o.order_date, o.total_amount, o.final_amount, o.status, o.payment_status, o.shipping_method, o.tracking_number, o.created_time, COUNT(oi.item_id) as item_count FROM orders o LEFT JOIN order_item oi ON o.order_id = oi.order_id
AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND o.customer_name LIKE CONCAT('%', #{customerName}, '%')
AND o.customer_phone LIKE CONCAT('%', #{customerPhone}, '%')
AND o.status = #{status}
AND o.payment_status = #{paymentStatus}
AND o.order_date >= #{orderDateStart}
AND o.order_date <= #{orderDateEnd}
AND o.final_amount >= #{minAmount}
AND o.final_amount <= #{maxAmount}
AND o.payment_method = #{paymentMethod}
AND o.shipping_method = #{shippingMethod}
GROUP BY o.order_id, o.order_no, o.customer_name, o.customer_phone, o.order_date, o.total_amount, o.final_amount, o.status, o.payment_status, o.shipping_method, o.tracking_number, o.created_time ORDER BY o.order_date DESC, o.order_id DESC

SELECT COUNT(*) as total_orders, COUNT(CASE WHEN status = 'PENDING' THEN 1 END) as pending_orders, COUNT(CASE WHEN status = 'PROCESSING' THEN 1 END) as processing_orders, COUNT(CASE WHEN status = 'SHIPPED' THEN 1 END) as shipped_orders, COUNT(CASE WHEN status = 'DELIVERED' THEN 1 END) as delivered_orders, COUNT(CASE WHEN status = 'CANCELLED' THEN 1 END) as cancelled_orders, COUNT(CASE WHEN payment_status = 'PAID' THEN 1 END) as paid_orders, COUNT(CASE WHEN payment_status = 'PENDING' THEN 1 END) as unpaid_orders, SUM(final_amount) as total_amount, AVG(final_amount) as avg_amount, MAX(final_amount) as max_amount, MIN(final_amount) as min_amount FROM orders
AND order_date >= #{startDate}
AND order_date <= #{endDate}

SELECT DATE(order_date) as order_day, COUNT(*) as order_count, SUM(final_amount) as daily_sales, AVG(final_amount) as avg_order_value, COUNT(DISTINCT customer_phone) as unique_customers FROM orders
AND order_date >= #{startDate}
AND order_date <= #{endDate}
GROUP BY DATE(order_date) ORDER BY order_day DESC

SELECT YEAR(order_date) as year, MONTH(order_date) as month, DATE_FORMAT(order_date, '%Y-%m') as year_month, COUNT(*) as order_count, SUM(final_amount) as monthly_sales, AVG(final_amount) as avg_order_value, COUNT(DISTINCT customer_phone) as unique_customers FROM orders
AND YEAR(order_date) >= #{startYear}
AND YEAR(order_date) <= #{endYear}
GROUP BY YEAR(order_date), MONTH(order_date) ORDER BY year DESC, month DESC

SELECT oi.product_name, oi.product_sku, oi.product_category, SUM(oi.quantity) as total_quantity, COUNT(DISTINCT oi.order_id) as order_count, SUM(oi.total_price) as total_sales, AVG(oi.unit_price) as avg_unit_price, RANK() OVER (ORDER BY SUM(oi.quantity) DESC) as quantity_rank, RANK() OVER (ORDER BY SUM(oi.total_price) DESC) as sales_rank FROM order_item oi JOIN orders o ON oi.order_id = o.order_id
AND o.order_date >= #{startDate}
AND o.order_date <= #{endDate}
GROUP BY oi.product_name, oi.product_sku, oi.product_category ORDER BY total_quantity DESC, total_sales DESC
LIMIT #{limit}

SELECT o.customer_name, o.customer_phone, o.customer_email, COUNT(o.order_id) as order_count, SUM(o.final_amount) as total_consumption, AVG(o.final_amount) as avg_order_value, MAX(o.final_amount) as max_order_value, MIN(o.final_amount) as min_order_value, MAX(o.order_date) as last_order_date, MIN(o.order_date) as first_order_date, DATEDIFF(MAX(o.order_date), MIN(o.order_date)) as customer_lifetime_days, CASE WHEN COUNT(o.order_id) >= 10 THEN 'VIP' WHEN COUNT(o.order_id) >= 5 THEN 'GOLD' WHEN COUNT(o.order_id) >= 2 THEN 'SILVER' ELSE 'BRONZE' END as customer_level FROM orders o
AND o.customer_id = #{customerId}
AND o.order_date >= #{startDate}
AND o.order_date <= #{endDate}
GROUP BY o.customer_phone, o.customer_name, o.customer_email ORDER BY total_consumption DESC, order_count DESC

SELECT
status,
COUNT(*) as status_count,
ROUND((COUNT(*) * 100.0 / total.total_orders), 2) as percentage,
AVG(DATEDIFF(updated_time, created_time)) as avg_days_in_status
FROM orders o
CROSS JOIN (
SELECT COUNT(*) as total_orders
FROM orders


        AND order_date >= #{orderDateStart}


        AND order_date <= #{orderDateEnd}


) total


        AND o.order_date >= #{orderDateStart}


        AND o.order_date <= #{orderDateEnd}


GROUP BY status
ORDER BY status_count DESC

SELECT shipping_method, COUNT(*) as order_count, AVG(shipping_fee) as avg_shipping_fee, COUNT(CASE WHEN status = 'DELIVERED' THEN 1 END) as delivered_count, ROUND((COUNT(CASE WHEN status = 'DELIVERED' THEN 1 END) * 100.0 / COUNT(*)), 2) as delivery_rate, AVG(CASE WHEN status = 'DELIVERED' THEN DATEDIFF(updated_time, order_date) END) as avg_delivery_days FROM orders
AND order_date >= #{startDate}
AND order_date <= #{endDate}
GROUP BY shipping_method ORDER BY delivery_rate DESC, avg_delivery_days ASC
